  ["Utilitário"] = "Utility",
  ["A proposta é oferecer uma experiência prática e organizada, disponibilizando ferramentas para diagnóstico do sistema, testes de controles, gerenciamento de arquivos, conectividade, transferência de dados, informações do dispositivo e muito mais."] = "The goal is to offer a practical and organized experience, providing tools for system diagnostics, controller tests, file management, connectivity, data transfer, device information and much more.",
  ["APOIE O PROJETO"] = "SUPPORT THE PROJECT",
  ["AVISO"] = "NOTICE",
  ["Abra o app do seu banco, escolha Pix > Pagar com QR Code e aponte a câmera para a tela. Você escolhe o valor."] = "Open your bank's app, choose Pix > Pay with QR Code and point the camera at the screen. You choose the amount.",
  ["Abrir canal"] = "Open channel",
  ["Acesse pelo celular ou computador:\n"] = "Access it from your phone or computer:\n",
  ["Apoiar"] = "Support",
