  ["Gravar dados pendentes (sync)"] = "Flush pending data (sync)",
  ["Disponível: grava no cartão o que o sistema ainda guarda na memória"] = "Available: writes to the card what the system still holds in memory",
  ["Gravar dados pendentes?"] = "Flush pending data?",
  ["O comando sync grava no cartão os dados que o sistema ainda mantém na memória. Não apaga nem altera arquivos. Útil antes de desligar ou remover o cartão."] = "The sync command writes to the card the data the system still keeps in memory. It does not delete or change files. Useful before turning off or removing the card.",
  ["Gravar dados pendentes"] = "Flush pending data",
  ["TRIM (fstrim)"] = "TRIM (fstrim)",
  ["Disponível em: "] = "Available on: ",
  ["Indisponível: "] = "Unavailable: ",
  ["Executar TRIM?"] = "Run TRIM?",
  ["O fstrim informa ao cartão quais blocos estão livres, o que pode ajudar a manter a velocidade de gravação. Não apaga arquivos. Pode levar alguns minutos e precisa de permissão de administrador. Partições: "] = "fstrim tells the card which blocks are free, which can help keep write speed. It does not delete files. It may take a few minutes and needs administrator permission. Partitions: ",
  ["Limpar temporários do R36S PORT HUB"] = "Clean R36S PORT HUB temporary files",
  ["Indisponível: há uma instalação em andamento"] = "Unavailable: an installation is in progress",
  ["Disponível: restos de instalações interrompidas do próprio hub"] = "Available: leftovers of the hub's own interrupted installations",
  ["Limpar temporários?"] = "Clean temporary files?",
  ["Apaga somente as pastas temporárias de instalações interrompidas do R36S PORT HUB (em "] = "Deletes only the temporary folders of interrupted R36S PORT HUB installations (in ",
  ["). Jogos, ports e arquivos do sistema não são tocados."] = "). Games, ports and system files are not touched.",
  ["Limpar temporários"] = "Clean temporary files",
  ["EXECUTAR"] = "RUN",
  ["Nenhum cartão encontrado."] = "No card found.",
  ["Nenhuma partição deste cartão está montada."] = "No partition of this card is mounted.",
  ["Localizar arquivos duplicados?"] = "Find duplicate files?",
  ["Procura arquivos com o mesmo conteúdo (comparação por hash) em: "] = "Looks for files with the same content (hash comparison) in: ",
  [". Arquivos menores que 1 MB são ignorados. Somente leitura: nada é apagado. Em cartões cheios pode levar vários minutos."] = ". Files smaller than 1 MB are skipped. Read-only: nothing is deleted. On full cards it may take several minutes.",
  ["PROCURAR"] = "SEARCH",
  ["A desfragmentação não é recomendada para o microSD do R36S. O cartão usa memória flash: ler um arquivo em pedaços espalhados é tão rápido quanto em sequência, e reorganizar os arquivos só gastaria ciclos de gravação do cartão."] = "Defragmentation is not recommended for the R36S microSD. The card uses flash memory: reading a file in scattered pieces is as fast as reading it in sequence, and rearranging files would only spend the card's write cycles.",
  ["Para cuidar do cartão, use as outras ferramentas desta tela: verificar integridade, verificar erros, TRIM (quando suportado) e localizar duplicados."] = "To take care of the card, use the other tools on this screen: check integrity, check errors, TRIM (when supported) and find duplicates.",
  ["Otimizador e manutenção do microSD"] = "microSD optimizer and maintenance",
