  ["%d pasta(s) temporária(s) apagada(s)  •  %s liberados."] = "%d temporary folder(s) deleted  •  %s freed.",
  ["Para corrigir erros, desligue o console, faça backup do cartão e use um computador: no Windows, \"Verificar erros\" nas propriedades da unidade (FAT/exFAT); no Linux, fsck.exfat, fsck.vfat ou e2fsck com a partição desmontada."] = "To fix errors, turn off the console, back up the card and use a computer: on Windows, \"Check\" for errors in the drive properties (FAT/exFAT); on Linux, fsck.exfat, fsck.vfat or e2fsck with the partition unmounted.",
