  ["%d runtime(s) em libs/"] = "%d runtime(s) in libs/",
  ["Os runtimes são dos ports (libs/*.squashfs), separados dos arquivos do PortMaster. A verificação usa o atualizador de runtimes do hub: ele confere cada arquivo (md5), mostra o que falta e só baixa depois de você confirmar. Nenhum runtime é removido."] = "Runtimes belong to the ports (libs/*.squashfs), separate from the PortMaster files. The check uses the hub's runtimes updater: it checks each file (md5), shows what is missing and only downloads after you confirm. No runtime is removed.",
