  ["A/B: voltar"] = "A/B: back",
  ["Leia o QR Code com a câmera do celular para abrir a página de doação do LivePix (livepix.gg/lagdolira). Lá você escolhe o valor e paga com Pix. Não use a opção Pagar com QR Code do app do banco."] = "Scan the QR code with your phone camera to open the LivePix donation page (livepix.gg/lagdolira). There you choose the amount and pay with Pix. Do not use the bank app's Pay with QR Code option.",
  ["Atualização instalada: reinicie o app antes de continuar."] = "Update installed: restart the app before continuing.",
  ["Nenhum quadro da tela chegou à gravação."] = "No screen frames reached the recording.",
  ["No modo econômico a tela do hub tem no máximo 20 quadros por segundo."] = "In power-saving mode the hub screen runs at no more than 20 frames per second.",
  ["30 FPS usa mais o processador. Se o vídeo ficar travado, use 15 FPS."] = "30 FPS uses more CPU. If the video stutters, use 15 FPS.",
