  ["As capas guardadas no console serão apagadas e baixadas de novo quando aparecerem na tela. Ports instalados e o catálogo não mudam."] = "The covers stored on the console will be deleted and downloaded again when they appear on screen. Installed ports and the catalog do not change.",
  ["As preferências voltam ao padrão. Idioma, tema, brilho, FTP, favoritos, históricos e ports instalados não são alterados.\n\nUma cópia das preferências atuais fica em settings.antes_de_restaurar.txt."] = "Preferences go back to the defaults. Language, theme, brightness, FTP, favorites, histories and installed ports are not changed.\n\nA copy of the current preferences is kept in settings.antes_de_restaurar.txt.",
