  ["Últimos jogos abertos pela lista de Ports do EmulationStation (quando o sistema registra). Somente leitura."] = "Last games opened from the EmulationStation Ports list (when the system records it). Read only.",
  ["última atualização online: "] = "last online update: ",
  ["Nova versão do R36S PORT HUB disponível: "] = "New R36S PORT HUB version available: ",
  ["  •  Atualize agora: aperte SELECT ou vá em Configurações > Atualizações do hub > Atualização via rede."] = "  •  Update now: press SELECT or go to Settings > Hub updates > Network update.",
  ["Avisar quando sair versão nova"] = "Notify when a new version is out",
  ["Ao abrir o hub, confere o link oficial em segundo plano. Se houver versão nova, um aviso desliza no alto da tela inicial até você atualizar (SELECT abre a atualização). Nada é baixado sozinho."] = "When the hub opens, it checks the official link in the background. If there is a new version, a notice scrolls at the top of the home screen until you update (SELECT opens the update). Nothing is downloaded automatically.",
