  ["O original fica onde está. Depois abra a pasta de destino: Y ou Opções > Colar"] = "The original stays where it is. Then open the destination folder: Y or Options > Paste",
  ["O sistema não informou o espaço do cartão."] = "The system did not report the card space.",
  ["Onde as mensagens rápidas aparecem na tela. Uma notificação de exemplo mostra o lugar escolhido."] = "Where quick messages appear on screen. A sample notification shows the chosen spot.",
