  ["Relatório completo do console: sistema, armazenamento, memória RAM e PortMaster."] = "Full console report: system, storage, RAM and PortMaster.",
  ["Idioma de todo o aplicativo: Português (Brasil), English e Русский. A abre a tela de escolha; a mudança vale na hora, sem reiniciar."] = "Language of the whole app: Português (Brasil), English and Русский. A opens the selection screen; the change applies right away, without restarting.",
