  ["PORT HUB"] = "PORT HUB",
  ["Temas do EmulationStation"] = "EmulationStation themes",
  ["Abre a Loja de Temas do EmulationStation (Ferramentas de sistema): temas compatíveis com o sistema do console, com prévia, tamanho de tela e compatibilidade."] = "Opens the EmulationStation Theme Store (System tools): themes compatible with the console's system, with preview, screen size and compatibility.",
  ["Volta ao tema Wii Blue Edition, ao tamanho de texto padrão e liga as animações. Brilho e idioma não mudam."] = "Returns to the Wii Blue Edition theme and the default text size, and turns animations on. Brightness and language do not change.",
  ["O hub volta ao tema Wii Blue Edition, com o tamanho de texto padrão e as animações ligadas."] = "The hub returns to the Wii Blue Edition theme, with the default text size and animations on.",
  ["PortMaster: "] = "PortMaster: ",
  ["IMPORTAR"] = "IMPORT",
  ["INTERNO"] = "INTERNAL",
  ["O catálogo remoto de temas ainda não foi configurado.\n\nPor enquanto estão disponíveis o Wii Blue Edition, o Neon Grid Edition e o Tema Padrão."] = "The remote theme catalog has not been set up yet.\n\nFor now, Wii Blue Edition, Neon Grid Edition and the Default Theme are available.",
  ["Wii Blue Edition"] = "Wii Blue Edition",
  ["Neon Grid Edition"] = "Neon Grid Edition",
  ["Inspirado no menu de canais do Nintendo Wii: fundo azul profundo, cartões brancos arredondados, ícones azuis e seleção com contorno azul luminoso. Visual limpo, com animações discretas."] = "Inspired by the Nintendo Wii channel menu: deep blue background, rounded white cards, blue icons and a glowing blue selection outline. A clean look with subtle animations.",
  ["Interface gamer futurista: fundo quase preto com grade em perspectiva, cartões escuros com contorno luminoso, ícones neon em verde e ciano, destaques roxo e rosa e brilho controlado."] = "Futuristic gamer interface: near-black background with a perspective grid, dark cards with glowing outlines, green and cyan neon icons, purple and pink highlights and controlled glow.",
  ["Baixar todas as capas do catálogo"] = "Download all catalog covers",
  ["Baixa de uma vez as capas do catálogo que ainda não estão no console, em segundo plano (pode sair desta tela). Depois, as capas aparecem mesmo sem internet. A de novo cancela."] = "Downloads at once the catalog covers that are not on the console yet, in the background (you can leave this screen). Afterwards, covers show up even without internet. A again cancels.",
  ["baixando %d de %d"] = "downloading %d of %d",
  ["todas no console"] = "all on the console",
  ["%d faltando"] = "%d missing",
  ["Cancelar o download das capas?"] = "Cancel the cover download?",
  ["A capa em andamento termina e o download para. As capas já baixadas ficam no console."] = "The cover in progress finishes and the download stops. Covers already downloaded stay on the console.",
  ["CANCELAR DOWNLOAD"] = "CANCEL DOWNLOAD",
  ["Todas as capas do catálogo já estão no console."] = "All catalog covers are already on the console.",
  ["Sem internet: conecte o Wi-Fi para baixar as capas."] = "No internet: connect Wi-Fi to download the covers.",
  ["Baixar as capas?"] = "Download the covers?",
  ["%d capas do catálogo ainda não estão no console. Elas serão baixadas uma por vez, em segundo plano, e ficam guardadas no Cache de capas."] = "%d catalog covers are not on the console yet. They will be downloaded one at a time, in the background, and kept in the Cover cache.",
  ["Download das capas cancelado: %d baixadas."] = "Cover download canceled: %d downloaded.",
  ["Capas: %d baixadas, %d falharam."] = "Covers: %d downloaded, %d failed.",
  ["Capas: %d baixadas."] = "Covers: %d downloaded.",
  ["Ports de jogos, BIOS do sistema e utilitários: veja, baixe e instale."] = "Game ports, system BIOS and utilities: browse, download and install.",
  ["Jogos dos emuladores do console, lidos do EmulationStation, com as capas do gamelist."] = "The console's emulator games, read from EmulationStation, with the gamelist covers.",
  ["Todos os ports organizados por gênero e por tipo de ferramenta."] = "All ports organized by genre and by tool type.",
  ["Os ports instalados no console: abrir, atualizar ou desinstalar."] = "The ports installed on the console: open, update or uninstall.",
  ["Os ports que você marcou como favoritos (SELECT na lista)."] = "The ports you marked as favorites (SELECT in the list).",
  ["Fila, progresso, velocidade e histórico dos downloads. Também abre com START."] = "Download queue, progress, speed and history. Also opens with START.",
  ["Aparência, rede, FTP, armazenamento, bateria, controles e muito mais."] = "Appearance, network, FTP, storage, battery, controls and more.",
  ["Créditos, avisos, licenças e o canal do projeto."] = "Credits, notices, licenses and the project channel.",
  ["Desligar ou reiniciar o console."] = "Power off or restart the console.",
  ["Fecha o hub e volta ao EmulationStation."] = "Closes the hub and returns to EmulationStation.",
  ["Pastel Pop Edition"] = "Pastel Pop Edition",
  ["Visual claro e arredondado, inspirado nos menus do 3DS e do Wii U: moldura em degradê azul e roxo, fundo claro pontilhado com formas pastel, cartões brancos com bordas coloridas, barras em formato de pílula e tela inicial em carrossel."] = "A light, rounded look inspired by the 3DS and Wii U menus: blue-to-purple gradient frame, light dotted background with pastel shapes, white cards with colored borders, pill-shaped bars and a carousel home screen.",
  ["Volta ao tema Pastel Pop Edition, ao tamanho de texto padrão e liga as animações. Brilho e idioma não mudam."] = "Returns to the Pastel Pop Edition theme and the default text size, and turns animations on. Brightness and language do not change.",
  ["O hub volta ao tema Pastel Pop Edition, com o tamanho de texto padrão e as animações ligadas."] = "The hub returns to the Pastel Pop Edition theme, with the default text size and animations on.",
  ["O catálogo remoto de temas ainda não foi configurado.\n\nPor enquanto estão disponíveis o Pastel Pop Edition, o Wii Blue Edition, o Neon Grid Edition e o Tema Padrão."] = "The remote theme catalog has not been set up yet.\n\nFor now, Pastel Pop Edition, Wii Blue Edition, Neon Grid Edition and the Default Theme are available.",
  ["Descrição"] = "Description",
  ["EMULADOR PRÓPRIO"] = "OWN EMULATOR",
