  ["Meus ports"] = "My ports",
  ["Nenhum destaque no momento"] = "Nothing featured right now",
  ["Ports recentes"] = "Recent ports",
  ["Atalhos"] = "Shortcuts",
  ["\n\nMande esse arquivo no grupo do Telegram junto com uma descrição do que aconteceu. Para tirar o arquivo do console: FTP (Configurações > Rede e conectividade), Gerenciador de arquivos ou o cartão SD no PC.\n\nSenhas não entram no relatório."] = "\n\nSend this file to the Telegram group with a description of what happened. To get the file off the console: FTP (Settings > Network and connectivity), File manager or the SD card on a PC.\n\nPasswords are not included in the report.",
  ["\n\nOs saves atuais com o mesmo nome serão substituídos pelos do backup. Feche o jogo antes."] = "\n\nCurrent saves with the same name will be replaced by the ones in the backup. Close the game first.",
  ["  (o hub usa 640x480)"] = "  (the hub uses 640x480)",
  ["  (placa fora da base do hub)"] = "  (board not in the hub's database)",
