  ["Backup dos saves feito. Removendo o port…"] = "Saves backed up. Removing the port…",
  ["Backup e restauração dos saves dos ports instalados (pastas conf, saves, savedata e arquivos .sav dentro da pasta do jogo)."] = "Back up and restore the saves of installed ports (conf, saves and savedata folders and .sav files inside the game folder).",
  ["Backup feito: %d item(ns)."] = "Backup done: %d item(s).",
  ["Backup grande"] = "Large backup",
  ["Este port ainda não tem backup de saves."] = "This port has no save backup yet.",
  ["Fazendo backup dos saves…"] = "Backing up saves…",
  ["Fazer backup"] = "Back up",
  ["Junta num arquivo só as informações do aparelho, o diagnóstico e os últimos erros, sem senhas, para mandar no grupo do Telegram."] = "Puts the device info, the diagnostics and the latest errors into a single file, without passwords, to send to the Telegram group.",
  ["Juntando as informações…"] = "Gathering the information…",
  ["Memória RAM: %d MB visíveis no sistema; um R36S original (1 GB em 2 chips) mostra cerca de 975 MB."] = "RAM: %d MB visible to the system; an original R36S (1 GB on 2 chips) shows about 975 MB.",
  ["Memória livre para uso agora e o total visível no sistema. Num R36S de 1 GB o total aparece como cerca de 975 MB: o kernel e a GPU reservam o resto."] = "Memory free right now and the total visible to the system. On a 1 GB R36S the total shows as about 975 MB: the kernel and GPU reserve the rest.",
  ["Nenhum port instalado pelo hub."] = "No port installed by the hub.",
  ["Nenhum save encontrado na pasta deste port."] = "No saves found in this port's folder.",
  ["Não foi possível criar o relatório"] = "Could not create the report",
  ["Não foi possível gravar na pasta de backups."] = "Could not write to the backup folder.",
  ["O hub vai juntar num arquivo só as informações do aparelho, o diagnóstico e os últimos erros registrados, para você mandar no grupo do Telegram.\n\nO que aconteceu?"] = "The hub will put the device info, the diagnostics and the latest logged errors into a single file for you to send to the Telegram group.\n\nWhat happened?",
  ["O tar não conseguiu criar o arquivo: "] = "tar could not create the file: ",
  ["Os saves deste port ocupam %s. O backup vai ocupar espaço parecido no cartão. Continuar?"] = "This port's saves take %s. The backup will take a similar amount of space on the card. Continue?",
  ["Relatório pronto!"] = "Report ready!",
