  ["\n\nDá para editar pelo FTP, pelo Gerenciador de arquivos do PC ou com o cartão SD no PC."] = "\n\nYou can edit it over FTP, from a PC file manager or with the SD card on a PC.",
  ["\n\nPara adicionar uma senha, escreva uma por linha no arquivo:\n"] = "\n\nTo add a password, write one per line in the file:\n",
  ["\nArquivo em %d partes: todas serão usadas, como no PC."] = "\nArchive in %d parts: all of them will be used, like on a PC.",
  ["\nSuas senhas: %d"] = "\nYour passwords: %d",
  [" • %d PARTES"] = " • %d PARTS",
  ["%d do hub + %d suas"] = "%d from the hub + %d yours",
  ["Capa do pacote aplicada: "] = "Cover from the package applied: ",
  ["O arquivo está protegido por senha e nenhuma das senhas salvas funcionou. Adicione a senha certa no arquivo senhas.txt da pasta do hub (Configurações > Downloads > Senhas de arquivos compactados) e tente de novo."] = "The file is password-protected and none of the saved passwords worked. Add the right password to senhas.txt in the hub folder (Settings > Downloads > Archive passwords) and try again.",
  ["PARTE %d"] = "PART %d",
  ["Senhas de arquivos compactados"] = "Archive passwords",
  ["Senhas do hub: "] = "Hub passwords: ",
  ["\n\nSenhas dos grupos e arquivos em partes são tratados sozinhos. Depois de cada instalação bem-sucedida, o arquivo compactado é excluído."] = "\n\nGroup passwords and multi-part archives are handled automatically. After each successful install, the archive is deleted.",
  [" (ex.: baixados do Telegram)."] = " (e.g. downloaded from Telegram).",
  ["%d arquivo(s) prontos para instalar"] = "%d file(s) ready to install",
  ["%d arquivo(s) vão para a Central de Downloads e serão instalados um de cada vez."] = "%d file(s) will go to the Downloads Center and be installed one at a time.",
  ["%d partes"] = "%d parts",
  ["%d port(s) na pasta ports prontos para instalar: veja em Meus Ports."] = "%d port(s) in the ports folder ready to install: see My Ports.",
  ["Arquivos de port na pasta "] = "Port files in the folder ",
  ["Copie o .zip, .rar, .7z ou .tar do port para a pasta ports e volte aqui."] = "Copy the port's .zip, .rar, .7z or .tar to the ports folder and come back here.",
  ["Instalar todos"] = "Install all",
  ["Instalar todos?"] = "Install all?",
  ["Nenhum arquivo de port na pasta ports."] = "No port files in the ports folder.",
  ["Pasta ports"] = "Ports folder",
  ["Ports (.zip, .rar, .7z, .tar) que estão na pasta ports e ainda não foram instalados. Abra para instalar."] = "Ports (.zip, .rar, .7z, .tar) in the ports folder that are not installed yet. Open to install.",
  ["Prontos para instalar"] = "Ready to install",
  ["Todos já estão na fila."] = "All of them are already queued.",
  ["Origem: grupo do Telegram "] = "Source: Telegram group ",
  ["Baixado do grupo do Telegram %s."] = "Downloaded from the %s Telegram group.",
  ["Telegram "] = "Telegram ",
  ["Agradecimentos: "] = "Thanks: ",
  ["Data: "] = "Date: ",
  ["Arquivos .zip, .rar e .7z com senha são abertos sozinhos: o hub tenta as senhas dos grupos de ports (R36SPORTSBR e R36XBR) e as suas, do arquivo senhas.txt na pasta do hub (uma por linha). Se nenhuma funcionar, o hub pede a senha no teclado e pode salvar no senhas.txt. Arquivos em partes (part1.rar, .7z.001, .zip.001) são extraídos juntos, como no PC."] = "Password-protected .zip, .rar and .7z files open by themselves: the hub tries the port groups' passwords (R36SPORTSBR and R36XBR) and yours, from senhas.txt in the hub folder (one per line). If none works, the hub asks for the password on the keyboard and can save it to senhas.txt. Multi-part archives (part1.rar, .7z.001, .zip.001) are extracted together, like on a PC.",
  [" precisa de senha. Instale de novo para digitar a senha."] = " needs a password. Install it again to type the password.",
  ["Senha do arquivo"] = "Archive password",
  ["Senha incorreta. Digite de novo:"] = "Wrong password. Type it again:",
  ["Nenhuma senha salva funcionou. Digite a senha do arquivo:"] = "No saved password worked. Type the archive password:",
