  ["Não vou mais perguntar \"Como rodou?\" ao sair dos jogos."] = "I won't ask \"How did it run?\" when leaving games anymore.",
  ["O Knulli informa a placa deste aparelho e a Device Tree carregada confirma o modelo. A comparação com placas e clones catalogados não é usada aqui."] = "Knulli reports this device's board and the loaded Device Tree confirms the model. The comparison with cataloged boards and clones is not used here.",
