  ["O comando do Knulli não aceitou o ajuste."] = "The Knulli command did not accept the setting.",
  ["O gerenciador de rede do Knulli (connman) não está em execução. Ative o Wi-Fi nas configurações de rede do Knulli e volte aqui."] = "Knulli's network manager (connman) is not running. Enable Wi-Fi in the Knulli network settings and come back here.",
  ["O modelo vem do hardware informado pelo sistema, não do nome do firmware."] = "The model comes from the hardware reported by the system, not from the firmware name.",
  ["O que entra"] = "What's included",
  ["O que entra no backup"] = "What goes into the backup",
  ["O serviço Bluetooth não está rodando (sem agente ou sem adaptador)."] = "The Bluetooth service is not running (no agent or no adapter).",
  ["O sistema para de acertar o relógio pela internet até o console ser reiniciado (no Knulli, a sincronização volta sozinha ao ligar). A data e a hora atuais são mantidas."] = "The system stops setting the clock from the internet until the console is restarted (on Knulli, syncing comes back on its own at boot). The current date and time are kept.",
  ["OUTRO"] = "OTHER",
  ["Obrigado! Relatório salvo em Meus relatórios de compatibilidade."] = "Thanks! Report saved in My compatibility reports.",
  ["Os aparelhos pareados continuam salvos. O Knulli grava a escolha e mantém desligado depois de reiniciar."] = "Paired devices stay saved. Knulli remembers the choice and keeps it off after restarting.",
  ["Os apps do Knulli vêm da Knulli App Store (comunidade). Instale-a pelo site do projeto:\n"] = "Knulli apps come from the Knulli App Store (community). Install it from the project's website:\n",
  ["Os arquivos do backup substituem os atuais NOS MESMOS CAMINHOS: o progresso salvo depois desta data, nesses arquivos, será perdido. Arquivos que não estão no backup não são apagados nem alterados."] = "The backup files replace the current ones AT THE SAME PATHS: progress saved after this date, in those files, will be lost. Files that are not in the backup are not deleted or changed.",
  ["Os efeitos, cores e brilho do LED RGB ficam no menu do Knulli (Configurações do sistema > LED). O hub não altera esses ajustes."] = "The RGB LED effects, colors and brightness are in the Knulli menu (System settings > LED). The hub doesn't change these settings.",
