  ["O CHD confere: a tradução aparece em \"Para os seus jogos\"."] = "The CHD checks out: the translation shows up in \"For your games\".",
  ["O PPSSPP do Knulli lê .chd, mas só no formato DVD (\"createdvd\"). O chdman 0.251 do Debian 12 não tem esse comando, então o PSP fica de fora."] = "Knulli's PPSSPP reads .chd, but only in DVD format (\"createdvd\"). Debian 12's chdman 0.251 doesn't have that command, so PSP is left out.",
