  -- Apps do Knulli no tema Premium (cartoes e pagina do app)
  [" (sem item no menu)"] = " (no menu entry)",
  ["%d apps  •  %d instalados"] = "%d apps  •  %d installed",
  ["%s no menu %s"] = "%s in the %s menu",
  ["Abrir a Knulli App Store completa"] = "Open the full Knulli App Store",
  ["Aguarde: a Knulli App Store está trabalhando."] = "Please wait: the Knulli App Store is working.",
  ["Confere e repõe os arquivos do app"] = "Checks and restores the app's files",
  ["Cria"] = "Creates",
  ["Dependências"] = "Dependencies",
  ["Instalado ocupa"] = "Installed size",
  ["Licença"] = "License",
  ["Menu do Knulli › %s"] = "Knulli menu › %s",
  ["NOTAS DA REVISÃO"] = "REVIEW NOTES",
  ["O hub fecha e abre de novo ao sair da loja"] = "The hub closes and reopens when you leave the store",
  ["Os apps do Knulli vêm da Knulli App Store, uma loja da comunidade. Instale a loja pelo site do projeto e os apps aparecem aqui, com instalação e atualização pelo hub."] = "Knulli apps come from the Knulli App Store, a community store. Install the store from the project's site and the apps show up here, with install and update through the hub.",
  ["Repositório"] = "Repository",
  ["Rolar notas"] = "Scroll notes",
  ["Sem atalho no menu do Knulli"] = "No shortcut in the Knulli menu",
  ["Trabalhando…"] = "Working…",
  ["Versão na loja"] = "Store version",
  ["não usa"] = "not used",
  ["usa a rede"] = "uses the network",
  ["Os Apps do Knulli ainda não foram preparados."] = "Knulli Apps are not set up yet.",
  ["o baixador não respondeu"] = "the downloader did not respond",
  ["Já existe uma atualização dos Apps do Knulli em andamento."] = "A Knulli Apps update is already in progress.",
  ["Apps do Knulli: lista atualizada (%s)"] = "Knulli Apps: list updated (%s)",
  ["Aguarde: a lista dos Apps do Knulli está sendo atualizada."] = "Please wait: the Knulli Apps list is being updated.",
  ["Os Apps do Knulli funcionam pelo hub sem a loja instalada: o hub usa a própria cópia do instalador e da lista oficial.\n\nPara usar a interface completa da loja, instale-a pelo site do projeto:\n"] = "Knulli Apps work in the hub without the store installed: the hub uses its own copy of the installer and the official list.\n\nTo use the full store interface, install it from the project's site:\n",
  ["Os Apps do Knulli já estão sendo preparados."] = "Knulli Apps are already being set up.",
  ["Baixando os Apps do Knulli..."] = "Downloading Knulli Apps...",
  ["Apps do Knulli prontos (%s)"] = "Knulli Apps ready (%s)",
  ["Não foi possível preparar os Apps do Knulli"] = "Could not set up Knulli Apps",
  ["Confira a conexão com a internet e tente de novo. Nada foi alterado."] = "Check your internet connection and try again. Nothing was changed.",
  ["Preparar os Apps do Knulli?"] = "Set up Knulli Apps?",
  ["O hub baixa a versão mais nova da Knulli App Store (projeto da comunidade, GitHub oficial) e guarda só o instalador e a lista de apps assinada, da mesma versão.\n\nDownload: %s (o pacote traz a interface da loja, que é descartada).\nPasta: %s (não aparece no menu)."] = "The hub downloads the latest Knulli App Store release (community project, official GitHub) and keeps only the installer and the signed app list, from the same release.\n\nDownload: %s (the package includes the store interface, which is discarded).\nFolder: %s (not shown in the menu).",
  ["Preparar os Apps do Knulli"] = "Set up Knulli Apps",
  ["Os apps do Knulli vêm da Knulli App Store (comunidade). O hub pode baixar o instalador e a lista oficial de apps, sem instalar a loja em Ports.\n\nDownload: "] = "Knulli apps come from the Knulli App Store (community). The hub can download the installer and the official app list without installing the store in Ports.\n\nDownload: ",
  ["PREPARAR"] = "SET UP",
  ["Os apps do Knulli vêm da Knulli App Store, uma loja da comunidade. O hub baixa só o instalador e a lista oficial de apps (sem instalar a loja em Ports) e cuida da instalação e das atualizações."] = "Knulli apps come from the Knulli App Store, a community store. The hub downloads only the installer and the official app list (without installing the store in Ports) and handles installs and updates.",
  ["Baixando…"] = "Downloading…",
  ["Preparar"] = "Set up",
  -- apps do hub (lista "apps" do knulli-catalog.json, bin/hubapp.py)
  ["A instalação não foi concluída"] = "The installation was not completed",
  ["Se a troca de arquivos falhou, a versão anterior foi mantida. Registro: "] = "If replacing the files failed, the previous version was kept. Log: ",
  ["Remove a pasta do app (com os dados dele), o atalho e a capa do menu Tools."] = "Removes the app folder (including its data), the shortcut and the cover from the Tools menu.",
  ["App distribuído pelo Knulli Port Hub. Precisa de internet: o pacote vem das Releases do GitHub do hub e é conferido por sha256."] = "App distributed by Knulli Port Hub. Requires internet: the package comes from the hub's GitHub Releases and is verified by sha256.",
  ["Baixa a lista de apps da Knulli App Store (comunidade) para instalar pelo hub."] = "Downloads the Knulli App Store (community) app list to install through the hub.",
  -- pacote de musicas de games (core/musicpack.lua, ui/screens/musicpack.lua)
  ["Pacote de músicas de games"] = "Game music pack",
  ["32 remixes do OverClocked ReMix (Mario, Zelda, Sonic, Chrono Trigger...) para tocar no menu do Knulli. Baixa no console, com créditos."] = "32 OverClocked ReMix remixes (Mario, Zelda, Sonic, Chrono Trigger...) to play in the Knulli menu. Downloaded on the console, with credits.",
  ["%d faixas  •  ~%s no cartão  •  %d instaladas"] = "%d tracks  •  ~%s on the card  •  %d installed",
  ["%d faixas do OverClocked ReMix (arranjos de fãs, gratuitos). Download ~%s, ocupa ~%s no cartão (OGG 96 kbps) em %s.\n\nBaixa uma por vez dos espelhos oficiais do OC ReMix, confere e converte no console. Precisa de Wi-Fi; leva alguns minutos. Faixas já instaladas ficam como estão."] = "%d OverClocked ReMix tracks (free fan arrangements). Download ~%s, uses ~%s on the card (OGG 96 kbps) in %s.\n\nDownloads one at a time from the official OC ReMix mirrors, checks and converts them on the console. Requires Wi-Fi; takes a few minutes. Tracks already installed are kept as they are.",
  ["Aguarde: o pacote de músicas está trabalhando."] = "Please wait: the music pack is working.",
  ["Algumas faixas não foram instaladas"] = "Some tracks were not installed",
  ["Apaga só o que o pacote instalou: %d faixas em %s e a cópia das músicas do Knulli (%d). Outras músicas da pasta ficam.\n\nSem nenhuma música na pasta, o menu volta a tocar as do Knulli."] = "Deletes only what the pack installed: %d tracks in %s and the copy of the Knulli music (%d). Other music in the folder stays.\n\nWith no music left in the folder, the menu plays the Knulli music again.",
  ["Artista(s): "] = "Artist(s): ",
  ["Voltar: cancelar"] = "Back: cancel",
  ["Baixando %d de %d: %s"] = "Downloading %d of %d: %s",
  ["Cancelando…"] = "Cancelling…",
  ["Cancelar a instalação?"] = "Cancel the installation?",
  ["Convertendo %d de %d: %s"] = "Converting %d of %d: %s",
  ["Copia também as %d músicas do Knulli para %s/knulli."] = "Also copies the %d Knulli songs to %s/knulli.",
  ["Copiando as músicas do Knulli…"] = "Copying the Knulli music…",
  ["Créditos — OverClocked ReMix"] = "Credits — OverClocked ReMix",
  ["Créditos"] = "Credits",
  ["Duração: "] = "Duration: ",
  ["Instalar o pacote de músicas?"] = "Install the music pack?",
  ["Instalação cancelada. As faixas já instaladas ficaram."] = "Installation cancelled. Tracks already installed were kept.",
  ["Junto com as do Knulli"] = "Together with the Knulli music",
  ["Já existe uma operação do pacote de músicas em andamento."] = "A music pack operation is already running.",
  ["Músicas instaladas. Elas tocam no menu do Knulli."] = "Music installed. It plays in the Knulli menu.",
  ["Músicas: OverClocked ReMix (ocremix.org) — arranjos de fãs distribuídos gratuitamente. Os arranjos pertencem aos seus artistas; as composições originais, aos seus donos."] = "Music: OverClocked ReMix (ocremix.org) — fan arrangements distributed for free. The arrangements belong to their artists; the original compositions to their owners.",
  ["Não foi possível remover"] = "Could not remove",
  ["Não instalada"] = "Not installed",
  ["O menu toca só as músicas da pasta de músicas (as do Knulli deixam de tocar)."] = "The menu plays only the music in the music folder (the Knulli music stops playing).",
  ["O pacote de músicas não está instalado."] = "The music pack is not installed.",
  ["Pacote de músicas removido."] = "Music pack removed.",
  ["Para na faixa atual. As faixas já instaladas ficam (Remover apaga)."] = "Stops at the current track. Tracks already installed are kept (Remove deletes them).",
  ["Preparando…"] = "Preparing…",
  ["Página: "] = "Page: ",
  ["Removendo…"] = "Removing…",
  ["Remover o pacote de músicas?"] = "Remove the music pack?",
  ["SAIR DA TELA"] = "LEAVE SCREEN",
  ["Só as do pacote"] = "Only the pack music",
  ["Tente de novo mais tarde (Instalar baixa só o que falta). Registro: "] = "Try again later (Install downloads only what is missing). Log: ",
