  ["%d backup(s) excluído(s). %s liberados."] = "%d backup(s) deleted. %s freed.",
  ["%d excluído(s), %s liberados."] = "%d deleted, %s freed.",
  ["%d jogo(s)  •  backups ocupam %s"] = "%d game(s)  •  backups take %s",
  ["%d jogo(s) marcados como testados. As ROMs originais serão apagadas de vez; não dá para desfazer essas traduções depois. Libera %s."] = "%d game(s) marked as tested. The original ROMs will be deleted for good; these translations cannot be undone afterwards. Frees %s.",
  ["... e mais %d"] = "... and %d more",
  ["A ROM original será apagada de vez; não dá para desfazer a tradução depois. Libera %s."] = "The original ROM will be deleted for good; the translation cannot be undone afterwards. Frees %s.",
  ["A ROM traduzida não está no cartão; o backup é a única cópia do jogo e não foi apagado."] = "The translated ROM is not on the card; the backup is the only copy of the game and was not deleted.",
  ["A cópia da ROM original não está mais em %s. Não dá para desfazer; você pode só tirar o jogo do registro."] = "The copy of the original ROM is no longer at %s. It cannot be undone; you can only remove the game from the record.",
  ["A cópia da original sumiu; o jogo continua como está"] = "The copy of the original is gone; the game stays as it is",
  ["A versão traduzida é apagada (dá para traduzir de novo depois)."] = "The translated version is deleted (you can translate again later).",
  ["A ROM original volta de %s para o lugar da traduzida e o \" (PT-BR)\" sai do nome."] = "The original ROM comes back from %s in place of the translated one and \" (PT-BR)\" is removed from the name.",
