  ["O hub verifica 1 vez por dia, sem baixar o jogo: se o arquivo do servidor mudar (ou o link no catálogo), o item volta sozinho."] = "The hub checks once a day without downloading the game: if the file on the server changes (or the link in the catalog), the item comes back by itself.",
  ["O hub verifica 1 vez por dia, sem baixar o jogo: se o link voltar a responder com o arquivo (ou mudar no catálogo), o item volta sozinho."] = "The hub checks once a day without downloading the game: if the link serves the file again (or changes in the catalog), the item comes back by itself.",
