  ["ITENS ESCONDIDOS"] = "HIDDEN ITEMS",
  ["Itens do catálogo cujo download não funciona (link quebrado ou pacote inválido) saem da Central e da busca. Aqui dá para ver o motivo, verificar de novo e reativar. O hub também verifica sozinho, 1 vez por dia, e traz de volta o que voltar a funcionar."] = "Catalog items whose download doesn't work (broken link or invalid package) leave the Hub and search. Here you can see why, check again and restore them. The hub also checks by itself once a day and brings back whatever works again.",
