  ["Quando a conexão cai de vez, o download é cancelado ou o hub é fechado no meio, o que já foi baixado fica guardado: pedindo o mesmo download de novo, ele continua de onde parou. Parciais com mais de 7 dias ou de itens que saíram do catálogo são apagados sozinhos. Selecione para apagar todos agora."] = "When the connection drops for good, the download is cancelled or the hub is closed midway, what was already downloaded is kept: request the same download again and it continues where it stopped. Partials older than 7 days or from items that left the catalog are deleted automatically. Select to delete them all now.",
